mapper.select:
select 
from biz_project p left join biz_project parent on parent.project_id=p.parent_id and parent.del_flag='0'
left join sys_dept company on company.dept_id=p.company_dept_id and company.del_flag='0'


    p.del_flag='0'


            and p.main_owner_user_id=#{userId}



            and coalesce(p.sponsor_owner_user_id,p.initiator_user_id)=#{userId}


            and (p.main_owner_user_id=#{userId} or exists(
                select 1 from biz_project_member scope_member
                where scope_member.project_id=p.project_id and scope_member.user_id=#{userId}
                  and scope_member.status='0'))



        and (p.project_name like concat('%',#{keyword},'%')
          or p.project_no like concat('%',#{keyword},'%')
          or p.main_owner_name like concat('%',#{keyword},'%'))

    and p.status=#{status}
    and p.accounting_mode=#{accountingMode}
    and p.management_mode=#{managementMode}
    and p.close_method=#{closeMethod}
    and p.parent_id=#{parentId}
    and p.main_owner_user_id=#{mainOwnerUserId}

order by field(p.status,'PLANNING','ACTIVE','PAUSED','ACCEPTANCE','DRAFT','CLOSED','CANCELED'),
         p.priority='HIGH' desc,p.update_time desc,p.project_id desc

mapper.update:
update biz_project set budget_limit=#{budgetLimit},base_currency=#{baseCurrency},
  update_by=#{userName},update_time=sysdate(),version=version+1
where project_id=#{projectId} and del_flag='0' and version=#{version}

mapper.select:
select count(*) from biz_project_staff_allocation
where project_id=#{projectId} and user_id=#{userId} and status='ACTIVE'
  and effective_from<=coalesce(#{effectiveTo},'9999-12-31')
  and coalesce(effective_to,'9999-12-31')>=#{effectiveFrom}
  and allocation_id<>#{excludeAllocationId}

mapper.update:
update biz_project set main_owner_user_id=#{ownerUserId},main_owner_name=#{ownerName},
  update_by=#{userName},update_time=sysdate(),version=version+1
where project_id=#{projectId} and del_flag='0' and version=#{version}

update biz_project_milestone set status=#{status},actual_date=if(#{status}='DONE',current_date(),null),
  update_by=#{userName},update_time=sysdate()
where project_id=#{projectId} and milestone_id=#{milestoneId}

update biz_project_milestone set milestone_name=#{milestoneName},plan_date=#{planDate},
  actual_date=#{actualDate},weight=#{weight},status=#{status},sort_order=#{sortOrder},
  update_by=#{updateBy},update_time=sysdate(),remark=#{remark}
where milestone_id=#{milestoneId} and project_id=#{projectId}

update biz_project_risk set risk_type=#{riskType},risk_title=#{riskTitle},severity=#{severity},
  probability=#{probability},owner_user_id=#{ownerUserId},owner_name=#{ownerName},due_date=#{dueDate},
  status=#{status},response_plan=#{responsePlan},update_by=#{updateBy},update_time=sysdate(),remark=#{remark}
where risk_id=#{riskId} and project_id=#{projectId}

mapper.select:
select count(*) totalCount, sum(p.status='DRAFT') draftCount, sum(p.status='PLANNING') planningCount,sum(p.status='ACTIVE') activeCount, sum(p.status='PAUSED') pausedCount,sum(p.status='ACCEPTANCE') acceptanceCount, sum(p.status='CLOSED') closedCount, sum(p.status='PLANNING' and p.baseline_status='SUBMITTED') pendingPlanCount, sum(p.status='DRAFT' or (p.status='PLANNING' and p.baseline_status='SUBMITTED') or p.status in ('PAUSED','ACCEPTANCE')) pendingDecisionCount, sum(exists(select 1 from biz_project_task t where t.project_id=p.project_id and t.status<>'DONE' and t.due_date<current_date())) overdueProjectCount, sum(exists(select 1 from biz_project_risk r where r.project_id=p.project_id and r.status='OPEN' and r.severity in ('CRITICAL','HIGH'))) highRiskProjectCount from biz_project p where p.del_flag='0'
and coalesce(p.sponsor_owner_user_id,p.initiator_user_id)=#{userId}
and (p.main_owner_user_id=#{userId} or exists(select 1 from biz_project_member m where m.project_id=p.project_id and m.user_id=#{userId} and m.status='0'))

select from biz_project p left join biz_project parent on parent.project_id=p.parent_id and parent.del_flag='0' left join sys_dept company on company.dept_id=p.company_dept_id and company.del_flag='0'
where p.del_flag='0'
limit #{offset},#{pageSize}

select from biz_project p left join biz_project parent on parent.project_id=p.parent_id and parent.del_flag='0' left join sys_dept company on company.dept_id=p.company_dept_id and company.del_flag='0'
where p.del_flag='0' and (p.status='DRAFT' or (p.status='PLANNING' and p.baseline_status='SUBMITTED') or p.status in ('PAUSED','ACCEPTANCE'))
limit #{offset},#{pageSize}

select pending.* from (
union all union all union all union all union all union all union all
) pending order by pending.categoryOrder,pending.sortTime,pending.itemKey limit #{offset},#{pageSize}

select count(*) from biz_staff_leave_request
where user_id=#{userId} and status in ('PENDING','APPROVED','CANCEL_PENDING')
  and leave_start_date<=#{endDate} and leave_end_date>=#{startDate}
